// Đầu vào (1 item):
// { leadId?, level?, title, message, actions?: [{label, url}], emailTo?, emailHtml? }
const cfg = $('Cấu hình').first().json;
const input = $('Khi được gọi').first().json;

const title = String(input.title ?? '').trim();
const message = String(input.message ?? '').trim();
if (!title || !message) {
  throw new Error('Thông báo nhân viên: thiếu title hoặc message');
}

const level = ['HOT', 'WARM', 'COLD'].includes(input.level) ? input.level : null;
const actions = (Array.isArray(input.actions) ? input.actions : [])
  .filter((a) => a && a.label && /^https?:\/\//.test(String(a.url ?? '')))
  .map((a) => ({ label: String(a.label).slice(0, 40), url: String(a.url) }));

const esc = (t) => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const prefix = level === 'HOT' ? '[ƯU TIÊN] ' : '';
const subject = title.startsWith(prefix) ? title : prefix + title;

// Email: dùng HTML của luồng gọi nếu có, không thì dựng từ message + nút
const emailHtml = input.emailHtml
  ? String(input.emailHtml)
  : '<div style="font-family:Arial,sans-serif;max-width:600px;line-height:1.6">'
    + '<p><b>' + esc(subject) + '</b></p>'
    + '<p>' + esc(message).replace(/\n/g, '<br>') + '</p>'
    + actions.map((a) => '<a href="' + esc(a.url) + '" style="display:inline-block;margin-right:8px;background:#2563eb;color:#fff;padding:8px 14px;border-radius:6px;text-decoration:none">' + esc(a.label) + '</a>').join('')
    + '</div>';

// Telegram chỉ nhận nút bấm với link https. Link khác (vd. localhost khi chạy local) ghi thành dòng chữ.
const buttons = actions.filter((a) => a.url.startsWith('https://'));
const textLinks = actions.filter((a) => !a.url.startsWith('https://'));
const icon = { HOT: '🔴', WARM: '🟠', COLD: '⚪' }[level] ?? '🔔';
let text = icon + ' <b>' + esc(subject) + '</b>\n\n' + esc(message);
if (textLinks.length) text += '\n\n' + textLinks.map((a) => esc(a.label) + ': ' + esc(a.url)).join('\n');
if (text.length > 4000) text = text.slice(0, 3990) + '…';

const telegram = {
  chat_id: cfg.telegramChatId,
  text,
  parse_mode: 'HTML',
  disable_web_page_preview: true,
};
if (buttons.length) {
  telegram.reply_markup = { inline_keyboard: [buttons.map((b) => ({ text: b.label, url: b.url }))] };
}

return [{
  json: {
    leadId: input.leadId ?? null,
    level,
    emailTo: input.emailTo || cfg.staffEmail,
    subject,
    emailHtml,
    telegram,
  },
}];

const ran = $('Gửi Telegram').isExecuted;
const tg = ran ? $('Gửi Telegram').first().json : null;
return [{
  json: {
    emailSent: true,
    telegramSent: !!tg && tg.ok === true,
    telegramSkipped: !ran,
    telegramError: tg && tg.ok !== true ? (tg.error?.message ?? tg.description ?? 'Lỗi Telegram') : null,
  },
}];
